-- (ㄱ)
SELECT COUNT(*) FROM CUST CROSS JOIN GRADE;

-- (ㄴ)
SELECT COUNT(*) FROM CUST A
INNER JOIN GRADE B ON A.AMOUNT BETWEEN B.MIN_AMT AND B.MAX_AMT;

-- (ㄷ)
SELECT COUNT(*) FROM CUST A
FULL OUTER JOIN GRADE B ON A.AMOUNT BETWEEN B.MIN_AMT AND B.MAX_AMT;

SELECT COUNT(*)
FROM (
SELECT DISTINCT A, B
FROM Tbl_A
WHERE C IN (
SELECT D
FROM Tbl_B
WHERE UPPER(E) = 'E'
)
) X;

CREATE TABLE T1 (
COL1 NUMBER,
COL2 NUMBER,
CONSTRAINT CK_T1 CHECK (COL1 > 10 AND COL2 > 5)
);

CREATE VIEW V1 AS
SELECT DEPTNO, SUM(SAL) AS SS
FROM EMP GROUP BY DEPTNO;

create table t1 (no number);
insert into t1 values (1);
insert into t1 values (2);
savepoint sv1;
update t1 set no=4 where no=1;
savepoint sv1;
delete from t1 where no >= 2;
rollback to sv1;
insert into t1 values(3);
commit;
select max(no) from t1;

questions.explanation:
정답 ④

핵심 개념
같은 이름의 SAVEPOINT를 다시 선언하면 이전 것은 없어지고 마지막 선언 지점이 그 이름이 됩니다.

풀이 과정
단계 | 테이블
INSERT 1, 2 | {1, 2}
SAVEPOINT sv1 (나중에 덮어씀) | {1, 2}
UPDATE 1 → 4 | {4, 2}
SAVEPOINT sv1 (최종) | {4, 2}
DELETE no >= 2 | {}
ROLLBACK TO sv1 | {4, 2}
INSERT 3 | {4, 2, 3}
COMMIT | 확정
1. MAX(no) = 4.

선택지별 풀이
① 첫 번째 sv1로 돌아갔다고 본 값입니다.
② 근거 없는 값입니다.
③ UPDATE까지 취소됐다고 본 값입니다.
④ 정답. 4입니다.

함정 포인트
CREATE TABLE도 DDL이라 자동 커밋되지만 테이블이 비어 있어 영향이 없습니다.

